async fn describe(
    server: &Arc<SyncServer>,
    call: &FacadeCall<'_>,
    input: Result<serde_json::Value, FacadeApiError>,
) -> Result<FacadeCallOutput, FacadeApiError> {
    let auth = call.auth();
    auth.require(CoreScope::Read)?;
    auth.require_unrestricted_record_scope()?;
    let value = input?;
    oneiron::task_verb::sdk::validate_input("describe", &value)?;
    facade_outside_room_turn(call, "describe")?;
    let hooks = facade_hooks_pre(server, call, "describe", value).await?;
    let value = hooks.args.clone();
    if value.get("self").and_then(serde_json::Value::as_bool) == Some(true) {
        let (output, rows) =
            crate::api::context_board::describe_self_for_auth(server, auth, &value).await?;
        return Ok(FacadeCallOutput {
            value: facade_hooks_post(server, hooks, output).await?,
            rows: Some(rows),
        });
    }
    let (actor, class) = facade_actor(server, auth)?;
    facade_admit_readable_ref(&server.vault, auth, &value, "task_ref")?;
    let producers = oneiron::memory::ProducerRows::default();
    let output = facade_readable_task_rows(
        &server.vault,
        auth,
        oneiron::task_verb::sdk::describe(
            &credential_memory(&server.vault, Some(auth), actor, class)
                .at(auth.locality())
                .listing_producers(&producers),
            facade_input(value)?,
        )?,
    )?;
    let rows = Some(producers.take());
    Ok(FacadeCallOutput {
        value: facade_hooks_post(server, hooks, output).await?,
        rows,
    })
}
async fn tasks_create(
    server: &Arc<SyncServer>,
    call: &FacadeCall<'_>,
    input: Result<serde_json::Value, FacadeApiError>,
) -> Result<FacadeCallOutput, FacadeApiError> {
    let auth = call.auth();
    auth.require_granted(CoreScope::Write)?;
    let position = facade_landing(server, call)?;
    let value = input?;
    let (actor, class) = facade_actor(server, auth)?;
    let (server, owned) = (Arc::clone(server), call.owned());
    tokio::task::spawn_blocking(move || -> Result<FacadeCallOutput, FacadeApiError> {
        let call = owned.call();
        let producers = oneiron::memory::ProducerRows::default();
        let output = facade_invoke_born(
            &server,
            &call,
            actor,
            class,
            "tasks.create",
            value,
            position,
            &producers,
        )?;
        Ok(FacadeCallOutput::listed(output, &producers))
    })
    .await
    .map_err(|_| FacadeApiError::from(super::host_doors::internal("tasks.create")))?
}
