/// `vault.recall` → `SyncServer::recall_off_runtime_listing`, the recall door
/// every server transport shares (`POST /v1/core/facade/vault.recall`, and
/// the held socket's `rpc.req`): it embeds the query whenever the vault's
/// embedder is serving.
///
/// The lease is not a client input, and a bearer slip is not one. At high,
/// xhigh and max the door admits the recall on a line of its own and
/// reranks on the `[models]` reranker; its refusals (`BUDGET_SPENT`,
/// `MODEL_UNAVAILABLE`) are forwarded as those exact codes. With no
/// reranker route the recall runs unreranked and reports
/// `skipped / no_reranker` in `retrieval_meta.rerank`.
async fn vault_recall(
    server: &Arc<SyncServer>,
    call: &FacadeCall<'_>,
    input: Result<serde_json::Value, FacadeApiError>,
) -> Result<FacadeCallOutput, FacadeApiError> {
    let auth = call.auth();
    auth.require(CoreScope::Read)?;
    auth.require_lane_record_scope()?;
    let value = input?;
    oneiron::task_verb::sdk::validate_input("vault.recall", &value)?;
    let (actor, class) = facade_actor(server, auth)?;
    let hooks = facade_hooks_pre(server, call, "vault.recall", value).await?;
    let value = hooks.args.clone();
    let (output, listed) = server
        .recall_off_runtime_listing(
            actor,
            class,
            auth.verified_slip().cloned(),
            auth.locality(),
            call.room_turn()?,
            facade_input(value)?,
        )
        .await;
    let output = facade_output(output?)?;
    let rows = Some(listed);
    Ok(FacadeCallOutput {
        value: facade_hooks_post(server, hooks, output).await?,
        rows,
    })
}
async fn vault_export(
    server: &Arc<SyncServer>,
    call: &FacadeCall<'_>,
    input: Result<serde_json::Value, FacadeApiError>,
) -> Result<FacadeCallOutput, FacadeApiError> {
    let auth = call.auth();
    auth.require(CoreScope::Read)?;
    auth.require_unrestricted_record_scope()?;
    facade_outside_room_turn(call, "vault.export")?;
    if !auth.is_owner_grade() {
        return Err(FacadeApiError::forbidden(
            "full-vault export requires owner authority",
            ["Present a verified, unattenuated owner credential."],
        ));
    }
    let value = input?;
    oneiron::task_verb::sdk::validate_input("vault.export", &value)?;
    let proof = auth.verified_slip().ok_or_else(|| {
        FacadeApiError::forbidden(
            "full-vault export requires verified owner authority",
            ["Present a verified owner credential."],
        )
    })?;
    let hooks = facade_hooks_pre(server, call, "vault.export", value).await?;
    let input: oneiron::memory::ExportOptions = facade_input(hooks.args.clone())?;
    // Beside the archive, the rows its snapshot read past the
    // caller's locality: both owner paths list them.
    let (output, rows) = if proof.claims().holder_ref == "host" {
        server
            .vault
            .export_with_verified_host_owner_listing(&input, proof, auth.locality())?
    } else {
        let (actor, class) = facade_actor(server, auth)?;
        let producers = oneiron::memory::ProducerRows::default();
        let output = server
            .vault
            .memory(actor, class)
            .at(auth.locality())
            .listing_producers(&producers)
            .export_with_verified_owner(&input, proof)?;
        (output, producers.take())
    };
    let output = serde_json::to_value(output).map_err(|_| {
        FacadeApiError::new(
            StatusCode::INTERNAL_SERVER_ERROR,
            MEMORY_CODE_INTERNAL,
            "export result encoding failed",
            ["Report this SDK response mismatch."],
        )
    })?;
    Ok(FacadeCallOutput {
        value: facade_hooks_post(server, hooks, output).await?,
        rows: Some(rows),
    })
}
